  (gen_random_uuid(), 3, 'Composition', 'İş nesnesi yaşam döngüsü boyunca kendisine ait denetim geçmişini yönetiyor. Sahipliği nasıl modelliyorsun?', 'Geçmiş nesnesini işin bileşeni yapıp oluşturma ve kullanımını iş üzerinden yönetirim.', 'Geçmişi işin alt sınıfı yapıp bir geçmiş bir iştir ilişkisi kurarım.', 'Geçmiş verisini bütün işlerin ortak sınıf değişkeninde toplarım.', 'İş değişirken eski geçmişi yeni işe bağlayıp kayıt sahipliğini karıştırırım.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Composition', 'Fiyatlandırma davranışının çalışma anında değişebilmesi gerekiyor. Kalıtım ağını büyütmeden ne yaparsın?', 'Fiyatlandırma nesnesini bileşen olarak tutar ve gerektiğinde uyumlu başka nesneyle değiştiririm.', 'Her fiyat türü birleşimi için yeni bir alt sınıf oluştururum.', 'Davranışı büyük bir sınıf adı koşuluna bağlarım.', 'Strateji değişirken eski ve yeni nesneyi aynı anda duruma yazıp sonucu belirsiz bırakırım.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Static', '@@count alt sınıflar arasında paylaşıldığı için tür bazlı sayaçlar birbirini etkiliyor. Nasıl ayırırsın?', 'Her sınıfta class instance variable kullanır ve class methodlarıyla kendi sayacını yönetirim.', 'Aynı @@count değişkenini bütün hiyerarşide kullanıp sayaçların bağımsız olmasını beklerim.', 'Sayacı her nesnenin rastgele seçtiği global anahtarda tutarım.', 'Alt sınıf sayacını artırırken üst sınıf sayacını sıfırlarım.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Super', 'Alt method argüman alıyor fakat üst method hiç argüman beklemiyor. Ruby''de doğru super çağrısı nedir?', 'Mevcut argümanları iletmemek için super() çağırırım.', 'Parantezsiz super kullanıp bütün mevcut argümanların üst methoda gitmesini sağlarım.', 'super yazmadan üst methodun otomatik çalışacağını varsayarım.', 'Üst method hiç argüman beklemediği halde super(nil) ile sorunu gizlemeye çalışırım.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Super', 'Alt kurucu girdiyi normalize edip üst kurucuya düzeltilmiş değer gönderecek. Nasıl çağırırsın?', 'Normalize edilmiş değeri açıkça super(clean_name) ile üst kurucuya iletirim.', 'Parantezsiz super kullanıp özgün kirli argümanın otomatik iletilmesini kabul ederim.', 'Üst kurucunun alt sınıftaki yerel değişkeni kendiliğinden göreceğini varsayarım.', 'Hem kirli hem temiz değeri aynı üst alana sırayla yazıp sonucu belirsiz bırakırım.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Debugging', 'Dış çağıran private recalculate methodunu doğrudan çağırdığı için işlem duruyor. API sınırını nasıl düzeltirsin?', 'Dışarıya public bir işlem methodu sunar, private yardımcıyı sınıfın içinden çağırırım.', 'Private methodu dış çağıranların yine de kullanabileceğini varsayarım.', 'Bütün yardımcı methodları public yaparak kapsüllemeyi kaldırırım.', 'Görünürlük hatasını yakalamadan işlemi başarılı kaydederim.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 3, 'Debugging', 'Aynı adlı ikinci method tanımı ilkini değiştirdiği için tek argümanlı çağrı artık çalışmıyor. Kalıcı çözüm nedir?', 'Tek tanımda varsayılan veya değişken sayıda argümanı doğrulayarak desteklenen çağrıları yönetirim.', 'İki tanımı aynı adla yeniden sıralayıp ikisinin de korunacağını varsayarım.', 'Çağıranın hangi tanımın son yazıldığını tahmin etmesini beklerim.', 'Çalışmayan çağrıları sonuç üretmiş gibi kaydedip hatayı gizlerim.', 'object_oriented_programming', 3),
  (gen_random_uuid(), 1, 'Debugging', 'initialize içinde name = name yazıldığı için yeni kaydın adı daha sonra nil okunuyor. Neyi düzeltirsin?', 'Parametreyi nesnede saklamak için kurucuda @name = name ataması yaparım.', 'Yalnızca attr_reader :name ekleyip atama yapılmadan değerin oluşmasını beklerim.', 'Adı @@name sınıf değişkenine taşıyıp bütün kayıtların aynı değeri paylaşmasını sağlarım.', 'Eksik adı her okumada sabit bir metinle gizlerim.', 'object_oriented_programming', 1),
  (gen_random_uuid(), 1, 'Encapsulation', 'Teslimat sayacı dışarıdan görülebilsin ancak yalnızca başarılı teslimatta artsın. Erişimi nasıl kurarsın?', 'Sayacı attr_reader ile açar, artırmayı başarılı teslimatı yöneten methodda yaparım.', 'attr_accessor açıp çağıranların sayacı doğru artıracağına güvenirim.', 'Yalnızca attr_writer tanımlayıp güncel sayının okunmasını engellerim.', 'Sayacı bütün teslimat nesneleri için tek bir @@count alanında tutarım.', 'object_oriented_programming', 1),
